  const [impact,setImpact]=useState<BookingImpact|null>(null);
  const [form,setForm]=useState<BookingListItem|'new'|null>(null),[detail,setDetail]=useState<BookingListItem|null>(null),[report,setReport]=useState<BookingListItem[]|null>(null);
  const reload=useCallback(async()=>{const [bootstrap,list]=await Promise.all([requestJson<BookingBootstrap>('/bookings/bootstrap'),requestJson<BookingListItem[]>(`/bookings?trash=${trash}`)]);setData(bootstrap);setRows(list);setDrafts([]);setSelected([]);setRevision(v=>v+1);},[trash]);
  useEffect(()=>{let active=true;setError('');void reload().catch(e=>{if(active)setError(errorText(e));});return()=>{active=false;};},[reload]);
  useEffect(()=>{const params=new URLSearchParams(queryTarget),id=params.get('bookingId');if(id&&openedFromQuery.current!==queryTarget){const row=rows.find(r=>r.id===id);if(row){openedFromQuery.current=queryTarget;if(params.get('report')==='true'&&row.capabilities.report)setReport([row]);else setDetail(row);}}},[rows,queryTarget]);
  const guard=()=>{if(!gridDirty)return true;if(!window.confirm('Bỏ các thay đổi inline chưa lưu để chuyển thao tác?'))return false;setDrafts([]);setRevision(v=>v+1);return true;};
  const chosen=rows.filter(r=>selected.includes(r.id));const reportEligibility=bookingReportSelection(chosen);
  const bulkEdit=async(save:boolean)=>{if(!chosen.length||chosen.length>50||!guard())return;setBusy(true);setError('');try{
    if(bulkField==='quantity'&&new Set(chosen.map(r=>r.unit)).size>1)throw Error('Sửa số lượng hàng loạt cần các booking cùng đơn vị.');
    const body=command(chosen.map(r=>({id:r.id,recordVersion:r.recordVersion,fields:fields({...r,[bulkField]:bulkValue})})));const checked=await post<BookingCheck>('check',body);setBulkCheck(checked);if(save&&checked.valid){await post('batch-save',body);setBulkOpen(false);setBulkCheck(null);await reload();setNotice(`Đã sửa ${chosen.length} booking.`);}
  }catch(e){setError(errorText(e));}finally{setBusy(false);}};
  const action=async(a:BookingAction,target=chosen)=>{if(!target.length||target.length>50||!guard())return;if(['DELETE','PURGE'].includes(a)&&!window.confirm(`${a==='PURGE'?'Xóa vĩnh viễn':'Chuyển vào Thùng rác'} ${target.length} booking đã chọn?`))return;setBusy(true);setError('');try{const outcome=await post<{pending?:number}>('actions',{idempotencyKey:crypto.randomUUID(),action:a,items:target.map(r=>({id:r.id,recordVersion:r.recordVersion}))});await reload();setDetail(null);setNotice(outcome.pending?`Đã gửi ${outcome.pending} đề nghị cho LĐP; trạng thái hiện hành giữ nguyên trong lúc chờ.`:`Đã xử lý ${target.length} booking.`);}catch(e){setError(errorText(e));}finally{setBusy(false);}};
  const patchItems=(patches:SupplyGridPatch[])=>patches.map(p=>{const before=[...rows,...drafts].find(r=>r.id===p.id)!;const changed=fields({...before,...p.fields});const c=data?.contracts.find(c=>c.allocations.some(a=>a.id===changed.allocationId));if(!c)throw Error('Phân bổ không hợp lệ.');if(estimate(changed,c).unit!==before.unit&&!p.fields.quantity)throw Error('Đổi slot sang đơn vị khác: nhập lại số lượng trước khi lưu.');return p.id.startsWith('draft-')?{fields:changed}:{id:p.id,recordVersion:p.recordVersion,fields:changed};});
