  const duplicate=(row:BookingListItem)=>duplicateMany([row]);
  const canCreate=Boolean(capabilities['booking.create']&&data?.creatableAllocationIds?.length);
  const create=()=>{if(guard()){setPrefill(null);setDrafts([]);setRevision(v=>v+1);setForm('new');}};
  if(!data)return <div>{error?<p role="alert" className="text-rose-700">{error}</p>:<LoadingBlock label="Đang tải phân hệ đặt chỗ…"/>}</div>;
  const allocationsFor=(row:Record<string,unknown>)=>{const c=data.contracts.find(c=>c.contract.id===row.contractId);const original=c?.allocations.find(a=>a.id===row.allocationId);return c?.allocations.filter(a=>!a.supersededAt&&a.status==='APPROVED'&&a.scopeKind==='ENTITLEMENT'&&a.periodId===original?.periodId&&a.beneficiaryLabel===original?.beneficiaryLabel).map(a=>({value:a.id,label:c.slots.find(s=>s.id===a.slotId)?.name??a.id}))??[];};
  const columns:SupplyGridColumn[]=[{key:'workflowActions',label:'Xử lý',width:185,render:r=><BookingWorkflowButtons rows={[r as unknown as BookingListItem]} onSaved={reload} disabled={gridDirty||String(r.id).startsWith('draft-')}/>},{key:'name',label:'Mã đặt chỗ',width:110,render:r=><div><button className="text-left font-semibold text-vna-blue underline" onClick={()=>{if(guard())setDetail(r as unknown as BookingListItem);}} disabled={String(r.id).startsWith('draft-')}>{String(r.id).startsWith('draft-')?'Booking mới (nháp)':String(r.id).slice(0,8)}</button>{!trash&&canCreate&&<button aria-label={`Nhân bản ${r.slotName}`} className="mt-2 block text-xs text-vna-blue" onClick={()=>duplicate(r as unknown as BookingListItem)}>Nhân bản inline</button>}</div>},
    {key:'campaignId',label:'Chiến dịch',editable:true,width:200,options:[{value:'',label:'Nhập tên chiến dịch khác…'},...data.campaigns.map(c=>({value:c.id,label:c.name}))],render:r=>String(r.campaignLabel)},
    {key:'campaignLabel',label:'Tên chiến dịch / tên khác',editable:true,editableWhen:r=>!r.campaignId,width:230},{key:'contractName',label:'Hợp đồng',width:220},{key:'periodName',label:'Kỳ phân bổ'},{key:'beneficiaryLabel',label:'CQĐV khai thác'},
    {key:'allocationId',label:'Slot',editable:true,optionsForRow:allocationsFor,width:220,render:r=>String(r.slotName)},...(['startDate','endDate'] as const).map((key,i)=>({key,label:i?'Kết thúc':'Bắt đầu',editable:true,type:'date' as const,width:165,validate:(r:Record<string,unknown>)=>{const value=String(r[key]??'');return value&&((r.overallStartDate&&value<String(r.overallStartDate))||(r.overallEndDate&&value>String(r.overallEndDate)))?'Ngoài thời gian tổng thể':null;}})),
    {key:'quantity',label:'Số lượng',editable:true,type:'number',width:130},{key:'unit',label:'Đơn vị',width:100},{key:'unitPrice',label:'Đơn giá',type:'number',width:140},{key:'priceBasis',label:'Cơ sở giá',width:100},{key:'amount',label:'Trước VAT',type:'number',width:145},{key:'vat',label:'VAT',type:'number',width:130},{key:'gross',label:'Có VAT',type:'number',width:145},
    {key:'distribution',label:'Phân bổ thời gian',width:200,render:r=>(r.timeDistribution as BookingFields['timeDistribution'])?.mode==='CUSTOM'?'Tùy chỉnh':'Tự động · Theo ngày'},{key:'stateLabel',label:'Trạng thái',width:315,render:r=><BookingStatusCell row={r as unknown as BookingView} data={data} now={now}/>},{key:'deadlines',label:'Hạn xử lý',width:255,render:r=><BookingDeadlinePanel row={r as unknown as BookingListItem} compact now={now}/>},{key:'reportLabel',label:'Báo cáo',width:160},{key:'materialUrl',label:'Tư liệu (URL)',editable:true,width:250},{key:'note',label:'Ghi chú',editable:true,width:250}];
  const firstKeys=['workflowActions','name','campaignId','allocationId','stateLabel','deadlines'];const orderedColumns=[...firstKeys.map(k=>columns.find(c=>c.key===k)!),...columns.filter(c=>!firstKeys.includes(c.key))];
  const campaignFilter=new URLSearchParams(location.search).get('campaignId');const visible=[...rows,...drafts].filter(r=>(!contractFilter||r.contractId===contractFilter)&&(!campaignFilter||r.campaignId===campaignFilter)&&`${r.campaignLabel} ${r.slotName} ${r.contractName} ${r.note}`.toLocaleLowerCase().includes(query.toLocaleLowerCase())).filter(r=>{const tasks=bookingDeadlines(r,now);return deadlineFilter==='ALL'||tasks.some(t=>deadlineFilter==='LATE'?t.state==='LATE':deadlineFilter==='DUE_SOON'?t.state==='ON_TIME'&&Date.parse(t.dueAt!)-now<=4*3600000:t.state===deadlineFilter);});
  const grouping=groupMode==='NONE'?undefined:{mode:groupMode,order:groupMode==='MONTH'?'NEWEST_FIRST' as const:'LABEL_ASC' as const,
    resolve:(row:Record<string,unknown>)=>bookingListGroup(row as unknown as BookingListItem,groupMode,!contractFilter)};
  return <div className="space-y-5"><header className="flex flex-wrap items-start justify-between gap-3"><div><p className="text-xs font-semibold uppercase tracking-widest text-vna-blue">Vận hành truyền thông</p><h1 className="mt-1 text-3xl font-semibold text-vna-blue-deep">Đặt chỗ</h1><p className="mt-2 text-sm text-slate-500">Quản lý từng booking · Nhập nhanh trên bảng · Nghiệm thu theo hợp đồng</p></div>{canCreate&&<Button onClick={create}><CpmsIcon name="add" size={18}/> Tạo đặt chỗ mới</Button>}</header><div className="flex flex-wrap items-center gap-3"><Button variant={view==='LIST'?'primary':'secondary'} onClick={()=>{if(guard())setView('LIST');}}>Danh sách</Button><Button variant={view==='MATRIX'?'primary':'secondary'} onClick={()=>{if(guard())setView('MATRIX');}}>Ma trận</Button><Button variant={view==='TIMELINE'?'primary':'secondary'} onClick={()=>{if(guard())setView('TIMELINE');}}>Timeline</Button><Button variant={!trash?'primary':'secondary'} onClick={()=>{if(guard())setTrash(false);}}>Đang sử dụng</Button><Button variant={trash?'primary':'secondary'} onClick={()=>{if(guard())setTrash(true);}}><CpmsIcon name="delete" size={18}/> Thùng rác</Button><input aria-label="Tìm booking" className={`${inputClass} max-w-xs`} placeholder="Tìm chiến dịch, slot, ghi chú…" value={query} onChange={e=>setQuery(e.target.value)}/><select aria-label="Lọc hợp đồng booking" className={`${inputClass} max-w-sm`} value={contractFilter} onChange={e=>setContractFilter(e.target.value)}><option value="">Tất cả hợp đồng</option>{data.contracts.map(c=><option key={c.contract.id} value={c.contract.id}>{c.contract.name}</option>)}</select><select aria-label="Lọc hạn xử lý đặt chỗ" className={`${inputClass} max-w-xs`} value={deadlineFilter} onChange={e=>setDeadlineFilter(e.target.value)}><option value="ALL">Tất cả hạn xử lý</option><option value="OVERDUE">Đang quá hạn</option><option value="DUE_SOON">Sắp đến hạn (4 giờ)</option><option value="ON_TIME">Đang trong hạn</option><option value="LATE">Có bước đã xử lý trễ</option></select><Button variant="ghost" disabled={busy} onClick={()=>{if(guard())void reload().catch(e=>setError(errorText(e)));}}>Tải lại</Button></div>{error&&<p role="alert" className="rounded-lg bg-rose-50 p-3 text-sm text-rose-700">{error}</p>}{notice&&<p role="status" className="text-sm text-vna-blue">{notice}</p>}{data.canManage&&!trash&&<BookingHistoricalImport onSaved={reload}/>} {selected.length>0&&<div className="flex flex-wrap items-center gap-2 rounded-xl border border-cyan-200 bg-cyan-50 p-3"><b className="mr-3 text-sm">Đã chọn {selected.length}</b><BookingWorkflowButtons rows={chosen} onSaved={reload} disabled={busy||gridDirty}/>{(trash?['RESTORE','PURGE']:['PAUSE','RESUME','DELETE']).map(a=><Button key={a} size="sm" variant="secondary" disabled={busy||chosen.length!==selected.length||selected.length>50||chosen.some(r=>!r.capabilities[a==='RESTORE'?'restore':a==='PURGE'?'purge':a==='DELETE'?'delete':'update']||a==='PAUSE'&&r.state!=='ACTIVE'||a==='RESUME'&&r.state!=='PAUSED'||a==='PURGE'&&Number(r.acceptedQty)>0)} onClick={()=>void action(a as BookingAction)}>{({RESTORE:'Phục hồi',PURGE:'Xóa vĩnh viễn',PAUSE:'Tạm dừng',RESUME:'Nối lại',DELETE:'Xóa'} as Record<string,string>)[a]}</Button>)}{!trash&&<Button size="sm" variant="secondary" disabled={busy||chosen.length!==selected.length||selected.length>50||chosen.some(r=>!r.capabilities.update)} onClick={()=>{setBulkOpen(v=>!v);setBulkCheck(null);}}>Sửa hàng loạt</Button>}<span title={reportEligibility.reason}><Button size="sm" disabled={!reportEligibility.allowed||chosen.length!==selected.length||selected.length>50} onClick={()=>{if(guard()){setRevision(v=>v+1);setReport(chosen);}}}>Báo cáo / nghiệm thu</Button></span>{!reportEligibility.allowed&&<span className="text-xs text-slate-600">{reportEligibility.reason}</span>}</div>}
    {bulkOpen&&chosen.length>0&&<div className="space-y-3 rounded-xl border border-cyan-200 bg-white p-4"><div className="flex flex-wrap items-center gap-3"><select aria-label="Trường sửa hàng loạt" className={inputClass} style={{maxWidth:250}} value={bulkField} onChange={e=>{setBulkField(e.target.value);setBulkValue('');setBulkCheck(null);}}>{[['note','Ghi chú'],['materialUrl','Link tư liệu'],['quantity','Số lượng (cùng đơn vị)'],['startDate','Ngày bắt đầu'],['endDate','Ngày kết thúc']].map(([key,label])=><option key={key} value={key}>{label}</option>)}</select><input aria-label="Giá trị sửa hàng loạt" className={inputClass} style={{maxWidth:350}} type={bulkField.endsWith('Date')?'date':'text'} value={bulkValue} onChange={e=>{setBulkValue(e.target.value);setBulkCheck(null);}}/><Button variant="secondary" disabled={busy} onClick={()=>void bulkEdit(false)}>Kiểm tra lô</Button><Button disabled={busy||chosen.some(r=>!r.capabilities.update)} onClick={()=>void bulkEdit(true)}>Lưu sửa {chosen.length} booking</Button></div><Issues check={bulkCheck}/></div>}{!form&&!report&&!detail&&<section className={panelClass}>{view==='TIMELINE'?<BookingTimeline rows={visible} data={data} onOpen={setDetail}/>:view==='MATRIX'?<BookingMatrix rows={visible} data={data} contractId={contractFilter} onOpen={setMatrixRows} onCreate={canCreate?(value)=>{if(value){if(guard()){setPrefill(value);setForm('new');}}else create();}:undefined}/>:<SupplyGrid key={`${trash}-${revision}`} rows={visible.map(r=>({...r,stateLabel:stateLabel(r),reportLabel:reportLabel(r)}))} columns={orderedColumns} {...(grouping?{grouping}:{})} storageKey="cpms.bookings.workflow.v2" spreadsheet rowNumbers onCreate={!trash&&canCreate?create:undefined} empty={query||contractFilter?<span>Không có đặt chỗ phù hợp. <button className="text-vna-blue underline" onClick={()=>{setQuery('');setContractFilter('');}}>Bỏ bộ lọc</button></span>:'Chưa có đặt chỗ.'} toolbar={(patches,ids)=><><label className="inline-flex items-center gap-2 text-xs font-semibold text-slate-700">Gộp nhóm<select aria-label="Gộp nhóm đặt chỗ" title="Theo tháng bắt đầu; mỗi booking chỉ xuất hiện trong một nhóm" className="rounded-lg border border-slate-300 bg-white px-2 py-1.5 text-xs font-normal" value={groupMode} onChange={e=>setGroupMode(e.target.value as BookingListGroupMode)}><option value="NONE">Không gộp</option><option value="MONTH">Theo tháng</option><option value="SLOT">Theo slot</option><option value="CAMPAIGN">Theo chiến dịch</option></select></label><Button size="sm" variant="secondary" disabled={busy||(!patches.length&&!ids.length)} onClick={()=>void preview(patches.length?patches:ids.map(id=>({id,fields:{},recordVersion:rows.find(r=>r.id===id)?.recordVersion??0})))}>Xem trước ảnh hưởng đến tình trạng slot</Button>{!trash&&canCreate&&ids.length>0&&<Button size="sm" variant="secondary" onClick={()=>duplicateMany(visible.filter(r=>ids.includes(r.id)).map(r=>({...r,...patches.find(p=>p.id===r.id)?.fields})))}>Nhân bản {ids.length} dòng</Button>}</>} contextActions={targets=>{
      const values=targets as unknown as BookingListItem[],persisted=values.filter(r=>!r.id.startsWith('draft-'));
      return [...(values.length===1&&persisted.length===1?[{label:'Xem / sửa thông tin',run:()=>{if(guard())setDetail(persisted[0]!);}}]:[]),...(!trash?[{label:`Nhân bản ${values.length} dòng`,disabled:!canCreate||values.length+drafts.length>50,run:()=>duplicateMany(values)},{label:'Sửa hàng loạt',disabled:persisted.length!==values.length||values.some(r=>!r.capabilities.update),run:()=>{if(guard()){setSelected(values.map(r=>r.id));setBulkOpen(true);setBulkCheck(null);}}},{label:'Báo cáo / nghiệm thu',disabled:persisted.length!==values.length||!bookingReportSelection(values).allowed,run:()=>{if(guard())setReport(values);}},{label:'Xóa dòng đã chọn',disabled:values.some(r=>!r.id.startsWith('draft-')&&!r.capabilities.delete),run:()=>{if(persisted.length)void action('DELETE',persisted);else setDrafts(rs=>rs.filter(r=>!values.some(v=>v.id===r.id)));}}]:[{label:'Phục hồi dòng đã chọn',disabled:values.some(r=>!r.capabilities.restore),run:()=>void action('RESTORE',values)}])];
    }} projectDraft={(raw,patch)=>{const r={...raw,...patch} as unknown as BookingListItem;const c=data.contracts.find(c=>c.contract.id===r.contractId);if(!c)return{};const q=estimate(r,c);if(r.allocationId===raw.allocationId){q.unit=String(raw.unit);q.unitPrice=String(raw.unitPrice);q.priceBasis=String(raw.priceBasis);q.taxRate=String(raw.taxRate);q.amount=bookingProduct(r.quantity,q.unitPrice,q.priceBasis);q.vat=bookingProduct(q.amount,q.taxRate);q.gross=bookingSum([q.amount,q.vat]);}return{...q,campaignLabel:data.campaigns.find(c=>c.id===r.campaignId)?.name??r.campaignLabel,slotName:c.slots.find(s=>s.id===c.allocations.find(a=>a.id===r.allocationId)?.slotId)?.name??r.slotName};}} canEdit={!trash} canEditRow={r=>String(r.id).startsWith('draft-')?Boolean(canCreate):Boolean((r.capabilities as BookingListItem['capabilities']).update)} onRestoreRows={restored=>setDrafts(current=>[...current,...restored.filter(row=>String(row.id).startsWith("draft-")&&!current.some(item=>item.id===row.id)) as unknown as typeof current])} onSave={save} onDirty={setGridDirty} draftRowIds={drafts.map(r=>r.id)} onDiscard={()=>setDrafts([])} onSelectionChange={setSelected}/>}{view==='LIST'&&<Totals rows={visible}/>}</section>}
    <p className="text-xs text-slate-500">Thao tác tối đa 50 dòng mỗi lần. Double-click để sửa, Shift-click chọn vùng ô, Ctrl+C / X / V và Ctrl+S. Nháp chưa giữ chỗ; gửi duyệt sẽ kiểm tra và giữ hạn mức.</p>
    {impact&&<Modal title="Xem trước ảnh hưởng đến tình trạng slot" onClose={()=>setImpact(null)}><BookingImpactPanel impact={impact} contexts={data.contracts} onClose={()=>setImpact(null)}/></Modal>}
    {matrixRows&&<Modal title="Đặt chỗ trong ô ma trận" onClose={()=>setMatrixRows(null)}><div className="space-y-3">{matrixRows.map(r=><div key={r.id} className="rounded-lg border bg-white p-3"><button className="font-semibold text-vna-blue underline" onClick={()=>{setDetail(r);setMatrixRows(null);}}>{r.campaignLabel} · {r.slotName}</button><p>{r.startDate} – {r.endDate} · {formatSupply(r.quantity)} {r.unit} · {stateLabel(r)}</p><BookingWorkflowButtons rows={[r]} onSaved={async()=>{await reload();setMatrixRows(null);}}/></div>)}</div></Modal>}{form&&<BookingForm data={data} prefill={prefill} defaultContractId={contractFilter} initial={form==='new'?null:form} onClose={()=>setForm(null)} onSaved={reload}/>}{detail&&<BookingDetail row={detail} data={data} onSaved={reload} onClose={()=>setDetail(null)} onEdit={()=>{setForm(detail);setDetail(null);}} onReport={()=>{setReport([detail]);setDetail(null);}} onAction={a=>void action(a,[detail])}/>}{report&&<ReportWorkspace rows={report} ctx={data.contracts.find(c=>c.contract.id===report[0]?.contractId)!} onClose={()=>setReport(null)} onSaved={reload}/>}
  </div>;
